package com.lamggm.rospocket;
import org.json.*;import java.nio.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class RobotCadTest {
 static byte[] dense(int count)throws Exception{byte[] small=RobotGlbNormalsTest.fixture("");ByteBuffer in=ByteBuffer.wrap(small).order(ByteOrder.LITTLE_ENDIAN);int n=in.getInt(12);JSONObject j=new JSONObject(new String(small,20,n,java.nio.charset.StandardCharsets.UTF_8));byte[] b=Arrays.copyOfRange(small,28+n,small.length);b=Arrays.copyOf(b,80+count*12);ByteBuffer bin=ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);for(int k=0;k<count*3;k++)bin.putInt(80+k*4,k%3);j.getJSONArray("buffers").getJSONObject(0).put("byteLength",b.length);j.getJSONArray("bufferViews").put(new JSONObject().put("buffer",0).put("byteOffset",80).put("byteLength",count*12));j.getJSONArray("accessors").put(new JSONObject().put("bufferView",3).put("componentType",5125).put("type","SCALAR").put("count",count*3));j.getJSONArray("meshes").getJSONObject(0).getJSONArray("primitives").getJSONObject(0).put("indices",3);return RobotGlbTest.glb(j.toString(),b);}
 @Test public void retainsEveryFaceBeyondLodLimitWithoutExpandingEveryVertex()throws Exception{byte[] input=dense(200000);assertThrows(IllegalArgumentException.class,()->RobotGlb.decode(input));RobotCad.Mesh m=RobotCad.decode(input);assertEquals(200000,m.triangles);assertEquals(4,m.chunks.size());long vertices=0,indices=0;for(RobotCad.Chunk c:m.chunks){vertices+=c.vertices.limit();indices+=c.indices.limit();assertTrue(c.vertices.limit()/10<=65535);assertEquals(0,c.indices.limit()%3);}assertEquals(600000,indices);assertTrue("Indexed vertices must be reused",vertices<1000);assertTrue(m.byteCount<1300000);}
 @Test public void smallPackedNormalsPositionsAndEmbeddedMaterialMatchLegacyDecoder()throws Exception{byte[] input=RobotGlbNormalsTest.fixture("");RobotCad.Mesh m=RobotCad.decode(input);RobotGlb.Triangle t=RobotGlb.decode(input).get(0);assertEquals(1,m.triangles);RobotCad.Chunk c=m.chunks.get(0);for(int k=0;k<3;k++){int i=Short.toUnsignedInt(c.indices.get(k))*10;for(int p=0;p<3;p++){assertEquals(t.xyz[k*3+p],c.vertices.get(i+p),1e-6);assertEquals(t.normals[k*3+p],c.vertices.get(i+3+p),1e-6);}}assertThrows(IllegalArgumentException.class,()->RobotCad.decode(RobotGlbNormalsTest.fixture("nan")));}
}
